                                       AND wrtb_text_syntaxregel IS NULL
                                       AND wrtb_num_vorkstellen IS NULL
                                       AND wrtb_num_nachkstellen IS NULL
                                       AND wrtb_num_rundng_einh IS NULL
                                       AND wrtb_num_minwert IS NULL
                                       AND wrtb_num_maxwert IS NULL
