                                       AND wrtb_bin_inhalttyp IS NULL)
                                      OR(wrtb_typ <> 'ZPKT'
                                         AND wrtb_zpkt_granularitaet IS NULL
                                         AND wrtb_zpkt_maxwert IS NULL
